#include <bits/stdc++.h>
using namespace std;

struct TreeNode {
    int val;
    TreeNode *left, *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

files.driver:
// input: values in level order, -1 means "no child"
int main() {
    int x; cin >> x;
    TreeNode* root = x == -1 ? nullptr : new TreeNode(x);
    queue<TreeNode*> q; if (root) q.push(root);
    while (!q.empty()) {
        TreeNode* cur = q.front(); q.pop();
        int l, r; cin >> l >> r;
        if (l != -1) { cur->left = new TreeNode(l); q.push(cur->left); }
        if (r != -1) { cur->right = new TreeNode(r); q.push(cur->right); }
    }
    cout << "maxDepth = " << Solution().maxDepth(root) << endl;
}
